  cleanup.push(() => {
    clearTimeout(longPress)
    for (const listeners of controlListeners.values()) {
      for (const stop of listeners.stops) stop()
    }
    controlListeners.clear()
    pendingText.clear()
    for (const button of buttonPresses.values()) button.controller.dispose()
    buttonPresses.clear()
    for (const button of momentaryButtons.values()) button.controller.dispose()
    momentaryButtons.clear()
    momentaryStates.clear()
  })
  cleanup.push(this.$watch(() => component.boundAuthenticated && component.boundFeedbackConnected, connected => {
    if (!connected) {
      for (const button of buttonPresses.values()) button.controller.release()
      for (const button of momentaryButtons.values()) button.controller.release()
    }
    refreshAvailability()
  }))
  cleanup.push(this.$watch('boundAvailability', () => { refreshAvailability(); showFeedback() }))
  const unwatch = this.$watch('boundState', showFeedback)
  cleanup.push(() => unwatch(), () => observer.disconnect(), () => toolbar?.remove(),
    () => closeOverlay(), () => closeLoginScreen())
  cleanup.push(() => { for (const [node] of disabledNodes) setAvailable(node, true) })
  this.__visualBindingCleanup = cleanup

  const style = element('style')
